1	import { Router, type Request } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  companySkillCreateSchema,
5	  companySkillFileUpdateSchema,
6	  companySkillImportSchema,
7	  companySkillProjectScanRequestSchema,
8	} from "@paperclipai/shared";
9	import { trackSkillImported } from "@paperclipai/shared/telemetry";
10	import { validate } from "../middleware/validate.js";
11	import { accessService, agentService, companySkillService, logActivity } from "../services/index.js";
12	import { forbidden } from "../errors.js";
13	import { assertCompanyAccess, getActorInfo } from "./authz.js";
14	import { getTelemetryClient } from "../telemetry.js";
15	
16	type SkillTelemetryInput = {
17	  key: string;
18	  slug: string;
19	  sourceType: string;
20	  sourceLocator: string | null;
21	  metadata: Record<string, unknown> | null;
22	};
23	
24	export function companySkillRoutes(db: Db) {
25	  const router = Router();
26	  const agents = agentService(db);
27	  const access = accessService(db);
28	  const svc = companySkillService(db);
29	
30	  function canCreateAgents(agent: { permissions: Record<string, unknown> | null | undefined }) {
31	    if (!agent.permissions || typeof agent.permissions !== "object") return false;
32	    return Boolean((agent.permissions as Record<string, unknown>).canCreateAgents);
33	  }
34	
35	  function asString(value: unknown): string | null {
36	    if (typeof value !== "string") return null;
37	    const trimmed = value.trim();
38	    return trimmed.length > 0 ? trimmed : null;
39	  }
40	
41	  function deriveTrackedSkillRef(skill: SkillTelemetryInput): string | null {
42	    if (skill.sourceType === "skills_sh") {
43	      return skill.key;
44	    }
45	    if (skill.sourceType !== "github") {
46	      return null;
47	    }
48	    const hostname = asString(skill.metadata?.hostname);
49	    if (hostname !== "github.com") {
50	      return null;
51	    }
52	    return skill.key;
53	  }
54	
55	  async function assertCanMutateCompanySkills(req: Request, companyId: string) {
56	    assertCompanyAccess(req, companyId);
57	
58	    if (req.actor.type === "board") {
59	      if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) return;
60	      const allowed = await access.canUser(companyId, req.actor.userId, "agents:create");
61	      if (!allowed) {
62	        throw forbidden("Missing permission: agents:create");
63	      }
64	      return;
65	    }
66	
67	    if (!req.actor.agentId) {
68	      throw forbidden("Agent authentication required");
69	    }
70	
71	    const actorAgent = await agents.getById(req.actor.agentId);
72	    if (!actorAgent || actorAgent.companyId !== companyId) {
73	      throw forbidden("Agent key cannot access another company");
74	    }
75	
76	    const allowedByGrant = await access.hasPermission(companyId, "agent", actorAgent.id, "agents:create");
77	    if (allowedByGrant || canCreateAgents(actorAgent)) {
78	      return;
79	    }
80	
81	    throw forbidden("Missing permission: can create agents");
82	  }
83	
84	  router.get("/companies/:companyId/skills", async (req, res) => {
85	    const companyId = req.params.companyId as string;
86	    assertCompanyAccess(req, companyId);
87	    const result = await svc.list(companyId);
88	    res.json(result);
89	  });
90	
91	  router.get("/companies/:companyId/skills/:skillId", async (req, res) => {
92	    const companyId = req.params.companyId as string;
93	    const skillId = req.params.skillId as string;
94	    assertCompanyAccess(req, companyId);
95	    const result = await svc.detail(companyId, skillId);
96	    if (!result) {
97	      res.status(404).json({ error: "Skill not found" });
98	      return;
99	    }
100	    res.json(result);
101	  });
102	
103	  router.get("/companies/:companyId/skills/:skillId/update-status", async (req, res) => {
104	    const companyId = req.params.companyId as string;
105	    const skillId = req.params.skillId as string;
106	    assertCompanyAccess(req, companyId);
107	    const result = await svc.updateStatus(companyId, skillId);
108	    if (!result) {
109	      res.status(404).json({ error: "Skill not found" });
110	      return;
111	    }
112	    res.json(result);
113	  });
114	
115	  router.get("/companies/:companyId/skills/:skillId/files", async (req, res) => {
116	    const companyId = req.params.companyId as string;
117	    const skillId = req.params.skillId as string;
118	    const relativePath = String(req.query.path ?? "SKILL.md");
119	    assertCompanyAccess(req, companyId);
120	    const result = await svc.readFile(companyId, skillId, relativePath);
121	    if (!result) {
122	      res.status(404).json({ error: "Skill not found" });
123	      return;
124	    }
125	    res.json(result);
126	  });
127	
128	  router.post(
129	    "/companies/:companyId/skills",
130	    validate(companySkillCreateSchema),
131	    async (req, res) => {
132	      const companyId = req.params.companyId as string;
133	      await assertCanMutateCompanySkills(req, companyId);
134	      const result = await svc.createLocalSkill(companyId, req.body);
135	
136	      const actor = getActorInfo(req);
137	      await logActivity(db, {
138	        companyId,
139	        actorType: actor.actorType,
140	        actorId: actor.actorId,
141	        agentId: actor.agentId,
142	        runId: actor.runId,
143	        action: "company.skill_created",
144	        entityType: "company_skill",
145	        entityId: result.id,
146	        details: {
147	          slug: result.slug,
148	          name: result.name,
149	        },
150	      });
151	
152	      res.status(201).json(result);
153	    },
154	  );
155	
156	  router.patch(
157	    "/companies/:companyId/skills/:skillId/files",
158	    validate(companySkillFileUpdateSchema),
159	    async (req, res) => {
160	      const companyId = req.params.companyId as string;
161	      const skillId = req.params.skillId as string;
162	      await assertCanMutateCompanySkills(req, companyId);
163	      const result = await svc.updateFile(
164	        companyId,
165	        skillId,
166	        String(req.body.path ?? ""),
167	        String(req.body.content ?? ""),
168	      );
169	
170	      const actor = getActorInfo(req);
171	      await logActivity(db, {
172	        companyId,
173	        actorType: actor.actorType,
174	        actorId: actor.actorId,
175	        agentId: actor.agentId,
176	        runId: actor.runId,
177	        action: "company.skill_file_updated",
178	        entityType: "company_skill",
179	        entityId: skillId,
180	        details: {
181	          path: result.path,
182	          markdown: result.markdown,
183	        },
184	      });
185	
186	      res.json(result);
187	    },
188	  );
189	
190	  router.post(
191	    "/companies/:companyId/skills/import",
192	    validate(companySkillImportSchema),
193	    async (req, res) => {
194	      const companyId = req.params.companyId as string;
195	      await assertCanMutateCompanySkills(req, companyId);
196	      const source = String(req.body.source ?? "");
197	      const result = await svc.importFromSource(companyId, source);
198	
199	      const actor = getActorInfo(req);
200	      await logActivity(db, {
201	        companyId,
202	        actorType: actor.actorType,
203	        actorId: actor.actorId,
204	        agentId: actor.agentId,
205	        runId: actor.runId,
206	        action: "company.skills_imported",
207	        entityType: "company",
208	        entityId: companyId,
209	        details: {
210	          source,
211	          importedCount: result.imported.length,
212	          importedSlugs: result.imported.map((skill) => skill.slug),
213	          warningCount: result.warnings.length,
214	        },
215	      });
216	      const telemetryClient = getTelemetryClient();
217	      if (telemetryClient) {
218	        for (const skill of result.imported) {
219	          trackSkillImported(telemetryClient, {
220	            sourceType: skill.sourceType,
221	            skillRef: deriveTrackedSkillRef(skill),
222	          });
223	        }
224	      }
225	
226	      res.status(201).json(result);
227	    },
228	  );
229	
230	  router.post(
231	    "/companies/:companyId/skills/scan-projects",
232	    validate(companySkillProjectScanRequestSchema),
233	    async (req, res) => {
234	      const companyId = req.params.companyId as string;
235	      await assertCanMutateCompanySkills(req, companyId);
236	      const result = await svc.scanProjectWorkspaces(companyId, req.body);
237	
238	      const actor = getActorInfo(req);
239	      await logActivity(db, {
240	        companyId,
241	        actorType: actor.actorType,
242	        actorId: actor.actorId,
243	        agentId: actor.agentId,
244	        runId: actor.runId,
245	        action: "company.skills_scanned",
246	        entityType: "company",
247	        entityId: companyId,
248	        details: {
249	          scannedProjects: result.scannedProjects,
250	          scannedWorkspaces: result.scannedWorkspaces,
251	          discovered: result.discovered,
252	          importedCount: result.imported.length,
253	          updatedCount: result.updated.length,
254	          conflictCount: result.conflicts.length,
255	          warningCount: result.warnings.length,
256	        },
257	      });
258	
259	      res.json(result);
260	    },
261	  );
262	
263	  router.delete("/companies/:companyId/skills/:skillId", async (req, res) => {
264	    const companyId = req.params.companyId as string;
265	    const skillId = req.params.skillId as string;
266	    await assertCanMutateCompanySkills(req, companyId);
267	    const result = await svc.deleteSkill(companyId, skillId);
268	    if (!result) {
269	      res.status(404).json({ error: "Skill not found" });
270	      return;
271	    }
272	
273	    const actor = getActorInfo(req);
274	    await logActivity(db, {
275	      companyId,
276	      actorType: actor.actorType,
277	      actorId: actor.actorId,
278	      agentId: actor.agentId,
279	      runId: actor.runId,
280	      action: "company.skill_deleted",
281	      entityType: "company_skill",
282	      entityId: result.id,
283	      details: {
284	        slug: result.slug,
285	        name: result.name,
286	      },
287	    });
288	
289	    res.json(result);
290	  });
291	
292	  router.post("/companies/:companyId/skills/:skillId/install-update", async (req, res) => {
293	    const companyId = req.params.companyId as string;
294	    const skillId = req.params.skillId as string;
295	    await assertCanMutateCompanySkills(req, companyId);
296	    const result = await svc.installUpdate(companyId, skillId);
297	    if (!result) {
298	      res.status(404).json({ error: "Skill not found" });
299	      return;
300	    }
301	
302	    const actor = getActorInfo(req);
303	    await logActivity(db, {
304	      companyId,
305	      actorType: actor.actorType,
306	      actorId: actor.actorId,
307	      agentId: actor.agentId,
308	      runId: actor.runId,
309	      action: "company.skill_update_installed",
310	      entityType: "company_skill",
311	      entityId: result.id,
312	      details: {
313	        slug: result.slug,
314	        sourceRef: result.sourceRef,
315	      },
316	    });
317	
318	    res.json(result);
319	  });
320	
321	  return router;
322	}
